SELECT hemu.DUM_MONTH AS chargeMonth, ec.CODE_NAME AS energyTypeName, SUM(hemu.TOTAL_ENERGY_USAGE_QTY) AS usageQty, SUM(hemu.TOTAL_ENERGY_CHARGE_AMT) AS chargeAmt FROM HOUSEHOLD_ENERGY_MONTHLY_USAGE hemu LEFT JOIN COMMON_CODE ec ON ec.CODE_GROUP = 'ENEG' AND ec.CODE_VALUE = hemu.ENEG_TYPE WHERE hemu.UNIT_ID = #{unitId} AND hemu.DUM_MONTH IN
#{month}
GROUP BY hemu.DUM_MONTH, ec.CODE_NAME ORDER BY hemu.DUM_MONTH, ec.CODE_NAME

